      4'b1010: F = 1'b1;
      4'b1011: F = 1'b0;
      4'b1100: F = 1'b0;
      4'b1101: F = 1'b1;
      4'b1110: F = 1'b1;
      4'b1111: F = 1'b0;
    endcase
  end

endmodule
